"""The server's pages the app shows in its sheet (JUSPRIN_V2_WEB_PAGES):
Credits and plans, Billing and usage, and the checkout around them. Anything
about dollars is drawn here, so a price change never needs an app release.

The app opens them signed in through views.web_link, and closes its sheet when
a page goes to views.web_done, which is where every purchase, plan change and
cancel ends. From the welcome, before anyone has signed in, the app opens
Credits and plans with ?guest=1: the signed-out version, whose buttons close
the sheet so the person signs up on the app's own screens.
"""
from datetime import datetime, timedelta
from typing import Dict, List, Optional

import chargebee
from django.conf import settings
from django.contrib.auth import logout
from django.http import HttpResponseRedirect
from django.shortcuts import render
from django.urls import reverse
from django.utils import timezone
from django.views.decorators.http import require_GET, require_http_methods, require_POST

from jusprin.ledger import billing
from jusprin.ledger.account import USAGE_DAYS, _dollars, discounted_cents, usage
from jusprin.ledger.ledger import active_v2_plan, ensure_lots, has_paid, live_lots
from jusprin.models import JusPrinPlan

from .aliases import get_aliases

TIER_NAMES = {'basic': 'Standard', 'expert': 'Expert'}


def _day(when) -> str:
    """1 Dec"""
    when = timezone.localtime(when) if isinstance(when, datetime) else when
    return f'{when.day} {when:%b}'


def _credits(n: int) -> str:
    return f"{n:,} credit{'' if n == 1 else 's'}"


def _user(request):
    return request.user if request.user.is_authenticated else None


def _balance(user, now) -> int:
    ensure_lots(user.id, now)
    return sum(lot.credits_remaining for lot in live_lots(user.id, now))


def _message_prices() -> str:
    """"A Standard message is 1 credit and an Expert message is 5.", from the aliases."""
    by_tier = {}
    for alias in get_aliases().values():
        by_tier.setdefault(alias.tier, alias.credits)
    basic, expert = by_tier.get('basic'), by_tier.get('expert')
    if basic is None or expert is None:
        return ''
    return f'A Standard message is {_credits(basic)} and an Expert message is {expert}.'


def _launch_ends_day() -> str:
    """The offer's last day, in the time zone the offer's end is written in: it
    ends at the start of the next day there."""
    last = settings.JUSPRIN_V2_LAUNCH_OFFER_ENDS - timedelta(seconds=1)
    return f'{last.day} {last:%b}'


def _term_credits(user, plan: JusPrinPlan, now) -> Dict:
    """What is left of the current term's credits, launch bonus included."""
    lots = live_lots(user.id, now).filter(source_ref__startswith=f'term:{plan.external_id}:{plan.plan_id}:')
    return {'left': sum(lot.credits_remaining for lot in lots), 'of': sum(lot.credits_granted for lot in lots)}


def _where_you_are(user, plan: Optional[JusPrinPlan], now) -> Dict:
    """The line at the top of Credits and plans: why the person is here and
    where what they buy goes."""
    if user is None:
        return {'line': 'Buying needs a JusPrin account. New accounts get '
                        f'{settings.JUSPRIN_V2_SIGNUP_CREDITS:,} free credits for their first month.'}
    if plan is None:
        return {'line': f'You have {_credits(_balance(user, now))}. What you buy goes to {user.email} '
                        'and is ready as soon as this closes.'}
    spec = settings.JUSPRIN_V2_PLANS[plan.plan_id]
    term = _term_credits(user, plan, now)
    ending = plan.expired_at is not None
    line = (f"You’re on {spec['name']}: {term['left']:,} of {term['of']:,} credits left, "
            f"{'ending' if ending else 'renewing'} {_day(plan.current_term_end)}." if plan.current_term_end
            else f"You’re on {spec['name']}.")
    others = [other['name'] for plan_id, other in settings.JUSPRIN_V2_PLANS.items() if plan_id != plan.plan_id]
    if others and not ending:
        line += (f" A switch to {others[0]} starts today; the days left on {spec['name']} come off the first "
                 'payment.')
    return {'line': line, 'billing': True}


def _amount(credits: int, launch: bool) -> Dict:
    return {'usual': f'{credits:,}', 'now': f'{credits * 2 if launch else credits:,}'}


def _cards(user, plan: Optional[JusPrinPlan], launch: bool) -> List[Dict]:
    """Credit pack, then each plan, with what its button does for this person."""
    premium = user is not None and billing.obico_premium(user)
    pack = settings.JUSPRIN_V2_PACK
    cards = [{
        'id': 'pack', 'name': 'Credit pack', 'price': _dollars(pack['cents']), 'per': 'once',
        'credits': _amount(pack['credits'], launch), 'unit': 'credits',
        'note': 'These credits never expire.', 'verb': 'Buy a credit pack',
    }]
    for plan_id, spec in settings.JUSPRIN_V2_PLANS.items():
        card = {
            'id': plan_id, 'name': spec['name'], 'price': _dollars(spec['cents']), 'per': 'a month',
            'credits': _amount(spec['credits'], launch), 'unit': 'credits a month',
            'extra': 'Standard messages cost 0 credits.' if spec.get('unlimited_basic') else '',
            'note': 'These credits reset each month. Unused ones don’t carry over.',
            'verb': f"Subscribe to {spec['name']}",
        }
        if premium:
            card.update(was=card['price'], price=_dollars(discounted_cents(spec['cents'])),
                        discount=f'With Obico Premium’s {settings.JUSPRIN_V2_OBICO_DISCOUNT_PERCENT}% off.')
        if plan is not None and plan.plan_id == plan_id:
            card['current'] = True
        elif plan is not None and plan.expired_at is None:
            card['verb'] = f"Switch to {spec['name']}"
        cards.append(card)
    return cards


@require_GET
def prices(request):
    """Credits and plans: the Credit pack, Hobby and Workshop with their prices,
    the launch offer and Obico Premium's discount."""
    if request.GET.get('guest'):
        # The app is signed out; whoever this browser was signed in as before
        # isn't the person looking now.
        logout(request)
    user = _user(request)
    now = timezone.now()
    launch = billing.launch_on(now)
    plan = active_v2_plan(user.id) if user else None
    return render(request, 'jusprin/v2/web/prices.html', {
        'title': 'Credits and plans',
        'signed_in': user is not None,
        'launch': launch,
        'launch_ends': _launch_ends_day(),
        'where': _where_you_are(user, plan, now),
        'message_prices': _message_prices(),
        'cards': _cards(user, plan, launch),
        'free_credits': settings.JUSPRIN_V2_FREE_CREDITS,
        'error': request.GET.get('error') == 'checkout',
    })


@require_POST
def checkout(request):
    """Starts Chargebee's checkout for the card's button: "pack" or a plan id."""
    user = _user(request)
    if user is None:
        return HttpResponseRedirect(reverse('jusprin_v2_web_prices'))
    what = request.POST.get('what', '')
    back = request.build_absolute_uri(reverse('jusprin_v2_web_checkout_done'))
    try:
        if what == 'pack':
            url = billing.pack_checkout(user, back)
        elif billing.is_v2_plan(what):
            url = billing.plan_checkout(user, what, back)
        else:
            return HttpResponseRedirect(reverse('jusprin_v2_web_prices'))
    except chargebee.APIError:
        return HttpResponseRedirect(reverse('jusprin_v2_web_prices') + '?error=checkout')
    return HttpResponseRedirect(url)


@require_GET
def checkout_done(request):
    """Where Chargebee sends the person back: what was added, and Back to your
    chat, which goes to the done address."""
    user = _user(request)
    bought = billing.finish_checkout(user, request.GET['id']) if user and request.GET.get('id') else None
    if bought is None:
        return HttpResponseRedirect(reverse('jusprin_v2_web_prices'))
    now = timezone.now()
    launch = billing.launch_on(now)
    if bought['kind'] == 'pack':
        added = bought['credits'] * (2 if launch else 1)
        heading = f'{added:,} credits added'
        what = (f"A {bought['credits']:,}-credit pack, doubled for the launch." if launch
                else f"A {bought['credits']:,}-credit pack.")
    else:
        spec = settings.JUSPRIN_V2_PLANS[bought['plan_id']]
        heading = f"You’re on {spec['name']}"
        what = (f"{spec['credits'] * 2:,} credits a month until {_launch_ends_day()}, then {spec['credits']:,}."
                if launch else f"{spec['credits']:,} credits a month.")
    return render(request, 'jusprin/v2/web/purchase_done.html', {
        'title': 'Credits and plans',
        'launch': launch,
        'heading': heading,
        'line': f'{what} They’re on {user.email}; you now have {_credits(_balance(user, now))}.',
        'email': user.email,
    })


def _usage_view(user, now) -> Dict:
    spent = usage(user, now)
    by_day = {row['date']: row['credits'] for row in spent['days']}
    today = timezone.localdate(now)
    days = [today - timedelta(days=back) for back in range(USAGE_DAYS - 1, -1, -1)]
    peak = max(by_day.values(), default=0) or 1
    bars = [{'day': _day(day), 'credits': by_day.get(day.isoformat(), 0),
             'height': round(100 * by_day.get(day.isoformat(), 0) / peak)} for day in days]
    rows = []
    for row in spent['activity']:
        day = _day(datetime.fromisoformat(row['date']).date())
        if row.get('kind') == 'report':
            rows.append({'day': day, 'chat': row['title'], 'tier': '', 'messages': '', 'credits': f"+{row['credits']}"})
        else:
            rows.append({'day': day, 'chat': row['title'] or 'A chat', 'tier': TIER_NAMES.get(row['tier'], ''),
                         'messages': row['messages'], 'credits': row['credits']})
    return {'credits': _credits(spent['credits']), 'peak': peak, 'bars': bars, 'axis': [bars[0], bars[len(bars) // 2], bars[-1]],
            'rows': rows}


def _plan_view(user, plan: Optional[JusPrinPlan], launch: bool) -> Optional[Dict]:
    if plan is None:
        return None
    spec = settings.JUSPRIN_V2_PLANS[plan.plan_id]
    premium = billing.obico_premium(user)
    price = _dollars(discounted_cents(spec['cents']) if premium else spec['cents'])
    credits = (f"{spec['credits'] * 2:,} credits a month until {_launch_ends_day()}, then {spec['credits']:,}."
               if launch else f"{spec['credits']:,} credits a month.")
    when = ''
    if plan.current_term_end:
        when = f"{'Ends' if plan.expired_at else 'Renews'} {_day(plan.current_term_end)}."
    return {
        'name': spec['name'],
        'price': f"{price} a month" + (f" with Obico Premium’s {settings.JUSPRIN_V2_OBICO_DISCOUNT_PERCENT}% off"
                                       if premium else ''),
        'line': f'{credits} {when}'.strip(),
        'ending': plan.expired_at is not None,
    }


@require_GET
def billing_page(request):
    """Billing and usage: the plan in dollars with Change plan and Cancel plan,
    Chargebee's portal for the payment method and invoices, and the credits used
    per day and per chat."""
    user = _user(request)
    if user is None:
        return render(request, 'jusprin/v2/web/message.html', {
            'title': 'Billing and usage', 'heading': 'Sign in to see your billing',
            'line': 'Open Billing and usage from JusPrin’s Preferences, signed in to your JusPrin account.'})
    now = timezone.now()
    launch = billing.launch_on(now)
    paid = has_paid(user.id)
    return render(request, 'jusprin/v2/web/billing.html', {
        'title': 'Billing and usage',
        'plan': _plan_view(user, active_v2_plan(user.id), launch),
        'card': billing.card_line(user) if paid else None,
        'paid': paid,
        'balance': _credits(_balance(user, now)),
        'usage': _usage_view(user, now),
        'days': USAGE_DAYS,
    })


@require_http_methods(['GET', 'POST'])
def cancel(request):
    """Cancel plan: what cancelling does, then the cancel itself, which stops
    the plan at the end of the term already paid for."""
    user = _user(request)
    plan = active_v2_plan(user.id) if user else None
    if plan is None or plan.expired_at is not None:
        return HttpResponseRedirect(reverse('jusprin_v2_web_billing'))
    if request.method == 'POST':
        try:
            billing.cancel_plan(user)
        except chargebee.APIError:
            return render(request, 'jusprin/v2/web/message.html', {
                'title': 'Billing and usage', 'heading': 'The plan couldn’t be cancelled',
                'line': 'Nothing changed. Try again in a minute.', 'back': reverse('jusprin_v2_web_billing')})
        return HttpResponseRedirect(reverse('jusprin_v2_web_done'))
    spec = settings.JUSPRIN_V2_PLANS[plan.plan_id]
    until = f' until {_day(plan.current_term_end)}' if plan.current_term_end else ''
    return render(request, 'jusprin/v2/web/cancel.html', {
        'title': 'Billing and usage',
        'heading': f"Cancel {spec['name']}?",
        'line': f"You keep {spec['name']} and its credits{until}, and it doesn’t renew. Credit packs you bought stay.",
    })


@require_GET
def portal(request):
    """Chargebee's portal, for the payment method and invoices; it comes back
    to Billing and usage."""
    user = _user(request)
    if user is None or not has_paid(user.id):
        return HttpResponseRedirect(reverse('jusprin_v2_web_billing'))
    return HttpResponseRedirect(billing.portal_url(user, request.build_absolute_uri(reverse('jusprin_v2_web_billing'))))
